//! Parser for names matching ShotKit's atomic-save temporary-file format.
//!
//! The format is `.shotkit-{PID}-{UNIX_NANOS}-{SEQ}.tmp`, generated by
//! `atomic_save_windows`. This module deliberately accepts only the basename
//! format and the numeric ranges used by that generator. A matching name is
//! only a candidate, not proof of ownership; callers must never make a
//! deletion decision from this parse result alone.

/// Numeric fields from a name matching ShotKit's temporary-file format.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TempRecoveryName {
    pub(crate) pid: u32,
    pub(crate) unix_nanos: u128,
    pub(crate) sequence: u64,
}

/// Parse a filename matching ShotKit's exact temporary-name format.
///
/// All fields must be nonempty ASCII decimal strings and fit the types used by
/// the generator (`u32`, `u128`, and `u64`). No path component is accepted.
/// Because the input is `&str`, callers must reject non-UTF-8 names before
/// calling. A successful parse does not establish that ShotKit created a file.
pub fn parse_temp_recovery_name(name: &str) -> Option<TempRecoveryName> {
    let body = name
        .strip_prefix(".shotkit-")
        .or_else(|| name.strip_prefix(".ShotKit-"))?
        .strip_suffix(".tmp")?;
    let (pid, rest) = body.split_once('-')?;
    let (unix_nanos, sequence) = rest.split_once('-')?;

    // Requiring ASCII digits also rejects extra separators, path separators,
    // signs, whitespace, and Unicode lookalikes before numeric conversion.
    if !is_ascii_decimal(pid) || !is_ascii_decimal(unix_nanos) || !is_ascii_decimal(sequence) {
        return None;
    }

    Some(TempRecoveryName {
        pid: pid.parse().ok()?,
        unix_nanos: unix_nanos.parse().ok()?,
        sequence: sequence.parse().ok()?,
    })
}

fn is_ascii_decimal(field: &str) -> bool {
    !field.is_empty()
        && (field.len() == 1 || !field.starts_with('0'))
        && field.bytes().all(|byte| byte.is_ascii_digit())
}

/// Settings-only legacy format; never accepted in an image-only directory.
pub fn is_settings_temp_name(name: &str) -> bool {
    let Some(body) = name
        .strip_prefix(".shotkit-settings-")
        .and_then(|n| n.strip_suffix(".tmp"))
    else {
        return false;
    };
    let Some((pid, sequence)) = body.split_once('-') else {
        return false;
    };
    is_ascii_decimal(pid)
        && is_ascii_decimal(sequence)
        && pid.parse::<u32>().is_ok()
        && sequence.parse::<u64>().is_ok()
}

#[cfg(test)]
mod tests {
    use super::{parse_temp_recovery_name, TempRecoveryName};

    #[test]
    fn parses_valid_generator_name_and_numeric_boundaries() {
        assert_eq!(
            parse_temp_recovery_name(".shotkit-42-1730000000000000000-7.tmp"),
            Some(TempRecoveryName {
                pid: 42,
                unix_nanos: 1_730_000_000_000_000_000,
                sequence: 7,
            })
        );
        assert_eq!(
            parse_temp_recovery_name(".shotkit-0-0-0.tmp"),
            Some(TempRecoveryName {
                pid: 0,
                unix_nanos: 0,
                sequence: 0,
            })
        );
        assert_eq!(
            parse_temp_recovery_name(&format!(
                ".shotkit-{}-{}-{}.tmp",
                u32::MAX,
                u128::MAX,
                u64::MAX
            )),
            Some(TempRecoveryName {
                pid: u32::MAX,
                unix_nanos: u128::MAX,
                sequence: u64::MAX,
            })
        );
    }

    #[test]
    fn rejects_similar_foreign_names_and_wrong_prefix_or_suffix() {
        for name in [
            "shotkit-42-173-7.tmp",
            ".shotkitx-42-173-7.tmp",
            ".shotkit-42-173-7.tmp.bak",
            ".shotkit-42-173-7.TMP",
            ".shotkit--173-7.tmp",
            ".shotkit-42--7.tmp",
            ".shotkit-42-173-.tmp",
            ".shotkit-42-173-7-extra.tmp",
            ".shotkit-042-173-7.tmp",
            ".shotkit-42-0173-7.tmp",
            ".shotkit-42-173-07.tmp",
        ] {
            assert_eq!(parse_temp_recovery_name(name), None, "accepted {name:?}");
        }
    }

    #[test]
    fn rejects_path_separators_and_unicode_digits() {
        for name in [
            ".shotkit-42-173-7/other.tmp",
            ".shotkit-42-173-7\\other.tmp",
            ".shotkit-４２-173-7.tmp",
            ".shotkit-42-١٧٣-7.tmp",
            ".shotkit-42-173-７.tmp",
        ] {
            assert_eq!(parse_temp_recovery_name(name), None, "accepted {name:?}");
        }
    }

    #[test]
    fn rejects_fields_outside_generator_integer_ranges() {
        assert_eq!(
            parse_temp_recovery_name(".shotkit-4294967296-1-1.tmp"),
            None
        );
        assert_eq!(
            parse_temp_recovery_name(".shotkit-1-340282366920938463463374607431768211456-1.tmp"),
            None
        );
        assert_eq!(
            parse_temp_recovery_name(".shotkit-1-1-18446744073709551616.tmp"),
            None
        );

        // Parsing a very long field remains bounded and fallible, without
        // allocating a copy of the candidate name.
        let huge = format!(".shotkit-{}-1-1.tmp", "9".repeat(100_000));
        assert_eq!(parse_temp_recovery_name(&huge), None);
    }
}

#[cfg(test)]
mod additional_tests {
    use super::*;
    #[test]
    fn legacy_formats_remain_exact() {
        assert!(parse_temp_recovery_name(".ShotKit-1-2-3.tmp").is_some());
        assert!(is_settings_temp_name(".shotkit-settings-1-2.tmp"));
        for name in [
            ".shotkit-abc.tmp",
            "x.shotkit-1-2-3.tmp",
            ".shotkit-settings-1-2-3.tmp",
            ".shotkit-settings-01-2.tmp",
        ] {
            assert!(parse_temp_recovery_name(name).is_none());
            assert!(!is_settings_temp_name(name));
        }
    }
}
